#include <cstdint>

struct View
{
    std::uint32_t* pixels;
    int width;
    int height;
    int stride;
};

std::uint32_t* pixelAt(View v, int x, int y) { return nullptr; }
View subView(View v, int x, int y, int w, int h) { return { nullptr, 0, 0, v.stride }; }
void fillRect(View v, int x, int y, int w, int h, std::uint32_t colour) {}

solution.solution.cpp:
#include <algorithm>
#include <cstdint>

struct View
{
    std::uint32_t* pixels;
    int width;
    int height;
    int stride;
};

std::uint32_t* pixelAt(View v, int x, int y)
{
    if (x < 0 || y < 0 || x >= v.width || y >= v.height) return nullptr;
    return v.pixels + static_cast<std::ptrdiff_t>(y) * v.stride + x;
}

View subView(View v, int x, int y, int w, int h)
{
    const int left{ std::max(x, 0) }, top{ std::max(y, 0) };
    const int right{ std::min(x + w, v.width) }, bottom{ std::min(y + h, v.height) };
    if (right <= left || bottom <= top) return { nullptr, 0, 0, v.stride };
    return { v.pixels + static_cast<std::ptrdiff_t>(top) * v.stride + left, right - left, bottom - top, v.stride };
}

void fillRect(View v, int x, int y, int w, int h, std::uint32_t colour)
{
    const View r{ subView(v, x, y, w, h) };
    for (int row{ 0 }; row < r.height; ++row)
    {
        std::uint32_t* line{ r.pixels + static_cast<std::ptrdiff_t>(row) * r.stride };
        for (int col{ 0 }; col < r.width; ++col) line[col] = colour;
    }
}

unitTests:
#include <vector>
// An image 5 wide, 4 high, stored with a stride of 8: three padding pixels at the end of every row.
static std::vector<std::uint32_t> blank() { return std::vector<std::uint32_t>(8 * 4, 0xDEAD); }
static int countOf(const std::vector<std::uint32_t>& m, std::uint32_t c) { int n{ 0 }; for (auto p : m) if (p == c) ++n; return n; }

TEST("pixelAt uses the stride") {
    auto mem{ blank() };
    View v{ mem.data(), 5, 4, 8 };
    CHECK(pixelAt(v, 0, 0) == mem.data());
    CHECK(pixelAt(v, 4, 0) == mem.data() + 4);
    CHECK(pixelAt(v, 0, 1) == mem.data() + 8);
    CHECK(pixelAt(v, 3, 2) == mem.data() + 19);
    CHECK(pixelAt(v, 5, 0) == nullptr);
    CHECK(pixelAt(v, 0, 4) == nullptr);
    CHECK(pixelAt(v, -1, 2) == nullptr);
}
TEST("sub-views share memory and clip") {
    auto mem{ blank() };
    View v{ mem.data(), 5, 4, 8 };
    View s{ subView(v, 1, 1, 3, 2) };
    CHECK(s.pixels == mem.data() + 9); CHECK_EQ(s.width, 3); CHECK_EQ(s.height, 2); CHECK_EQ(s.stride, 8);
    *pixelAt(s, 2, 1) = 7;
    CHECK_EQ(mem[2 * 8 + 3], 7u);
    View c{ subView(v, 3, -1, 10, 3) };
    CHECK(c.pixels == mem.data() + 3); CHECK_EQ(c.width, 2); CHECK_EQ(c.height, 2);
    View none{ subView(v, 6, 0, 2, 2) };
    CHECK(none.pixels == nullptr); CHECK_EQ(none.width, 0);
}
TEST("fill stays inside the view") {
    auto mem{ blank() };
    View v{ mem.data(), 5, 4, 8 };
    fillRect(v, 0, 0, 5, 4, 1);
    CHECK_EQ(countOf(mem, 1), 20);
    CHECK_EQ(countOf(mem, 0xDEAD), 12);
    CHECK_EQ(mem[5], 0xDEADu);
    fillRect(v, 3, 2, 10, 10, 2);
    CHECK_EQ(countOf(mem, 2), 4);
    CHECK_EQ(mem[2 * 8 + 5], 0xDEADu);
    fillRect(v, -3, -3, 4, 4, 3);
    CHECK_EQ(mem[0], 3u);
    CHECK_EQ(countOf(mem, 3), 1);
}
TEST("fill through a sub-view") {
    auto mem{ blank() };
    View v{ mem.data(), 5, 4, 8 };
    View s{ subView(v, 2, 1, 2, 2) };
    fillRect(s, 0, 0, 99, 99, 9);
    CHECK_EQ(countOf(mem, 9), 4);
    CHECK_EQ(mem[1 * 8 + 2], 9u); CHECK_EQ(mem[2 * 8 + 3], 9u); CHECK_EQ(mem[1 * 8 + 4], 0xDEADu);
}

